# Generated by Claude (Claude Code).
"""Train PeakCNN on the UHD 620 via DirectML, with freshly generated functions every epoch."""

import csv
import json
import time
from datetime import datetime
from pathlib import Path

import numpy as np
import torch
import torch.nn as nn
import torch_directml

from data import generate_batch
from model import NUM_SAMPLES, PeakCNN
from optim import Adam
from plot import plot_training_log

EPOCHS = 50
FUNCTIONS_PER_EPOCH = 12_800
BATCH_SIZE = 256
LEARNING_RATE = 1e-3
SEED = 0
PROJECT_DIR = Path(__file__).resolve().parent
# Each run gets runs/<date>_<time>/ with config.json, model.pt, log.csv and chart.png.
RUNS_DIR = PROJECT_DIR / "runs"
LOG_COLUMNS = ["epoch", "loss", "accuracy", "seconds", "functions_seen", "timestamp"]


def main() -> None:
    torch.manual_seed(SEED)
    rng = np.random.default_rng(SEED)
    device = torch_directml.device()

    model = PeakCNN(NUM_SAMPLES).to(device)
    optimizer = Adam(model.parameters(), lr=LEARNING_RATE)
    loss_fn = nn.CrossEntropyLoss()
    steps_per_epoch = FUNCTIONS_PER_EPOCH // BATCH_SIZE

    run_dir = RUNS_DIR / f"{datetime.now():%Y-%m-%d_%H-%M-%S}"
    run_dir.mkdir(parents=True)
    model_path = run_dir / "model.pt"
    log_path = run_dir / "log.csv"
    chart_path = run_dir / "chart.png"
    functions_seen = 0

    config = {
        "epochs": EPOCHS,
        "functions_per_epoch": FUNCTIONS_PER_EPOCH,
        "batch_size": BATCH_SIZE,
        "learning_rate": LEARNING_RATE,
        "seed": SEED,
        "num_samples": NUM_SAMPLES,
    }
    (run_dir / "config.json").write_text(json.dumps(config, indent=2) + "\n")

    with open(log_path, "w", newline="") as log_file:
        log = csv.writer(log_file)
        log.writerow(LOG_COLUMNS)

        for epoch in range(1, EPOCHS + 1):
            model.train()
            start = time.perf_counter()
            total_loss = 0.0
            total_correct = 0
            total_seen = 0

            for _ in range(steps_per_epoch):
                functions, labels = generate_batch(BATCH_SIZE, NUM_SAMPLES, rng)
                x = torch.from_numpy(functions).to(device)
                y = torch.from_numpy(labels).to(device)

                logits = model(x)
                loss = loss_fn(logits, y)

                optimizer.zero_grad()
                loss.backward()
                optimizer.step()

                total_loss += loss.item() * len(labels)
                total_correct += (logits.argmax(dim=1) == y).sum().item()
                total_seen += len(labels)

            state = {k: v.detach().cpu() for k, v in model.state_dict().items()}
            torch.save(state, model_path)

            seconds = time.perf_counter() - start
            mean_loss = total_loss / total_seen
            accuracy = total_correct / total_seen
            functions_seen += total_seen

            log.writerow([
                epoch,
                f"{mean_loss:.6f}",
                f"{accuracy:.6f}",
                f"{seconds:.3f}",
                functions_seen,
                datetime.now().isoformat(timespec="seconds"),
            ])
            log_file.flush()

            print(
                f"epoch {epoch:3d}/{EPOCHS}  "
                f"loss {mean_loss:.4f}  "
                f"acc {accuracy:.2%}  "
                f"({seconds:.1f} s)"
            )

    plot_training_log(log_path, chart_path)
    print(f"saved weights, training log and chart to {run_dir}")


if __name__ == "__main__":
    main()
